                id_value = None
                for (attr, value) in elem.attrib.items():
                    attr_local = attr.split('}')[-1].lower() if '}' in attr else attr.lower()
                    if attr_local == attr_name:
                        id_value = value
                        break
                if id_value is not None:
                    if scope == 'global':
